def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != self.dim:
        raise ValueError("Coordinate has incorrect dimension.")

    for i, v in enumerate(coord):
        if v < self.lower_bound[i] or v > self.upper_bound[i]:
            return

    self.frequencies[self._coord_to_index(coord)] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if weight < 0:
        raise ValueError("negative weight not supported")
    if weight == 0:
        return

    try:
        x, y = coord
    except Exception as e:
        raise ValueError("invalid coordinate") from e

    if x < self._edges[0] or x > self._edges[-1]:
        return

    if y < self._edges[0] or y > self._edges[-1]:
        return

    idx_x = self._find_bin(x)
    idx_y = self._find_bin(y)

    if idx_x < 0 or idx_y < 0:
        return

    self._counts[idx_x, idx_y] += weight

