            self.spec_version = self.SPEC_VERSIONS[type_value]
        except KeyError:
            raise SchemaFormatException(f"Invalid spec type: {type_value} in {inventory}")

    for name, field in self.fields.items():
        value = inventory.get(name)
        if value is None:
            if field.required:
                raise SchemaFormatException(f"Missing required field: {name} in {inventory}")
        else:
            try:
                self.validate_field(field, value)
            except SchemaFormatException as e:
