def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that the fixity block is a dict
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check that the fixity block only contains allowed keys
    allowed_keys = ["fixity_type", "fixity_value"]
    for key in fixity.keys():
        if key not in allowed_keys:
            raise ValueError("Fixity block contains invalid key: %s" % key)

    # Check that fixity_type is a string
    if "fixity_type" in fixity.keys() and not isinstance(fixity["fixity_type"], str):
        raise ValueError("fixity_type must be a string")

    # Check that fixity_value is a string
    if "fixity_value" in fixity.keys() and not isinstance(fixity["fixity_value"], str):
        raise ValueError("fixity_value must be a string")

    # Check that the fixity_value matches the fixity_type
    if "fixity_value" in fixity.keys() and "fixity_type" in fixity.keys():
        if fixity["fixity_type"] == "sha256":
            if not re.match(r"^\w{64}$", fixity["fixity_value"]):
                raise ValueError("fixity_value for sha256 must be a 64-character string")
        elif fixity["fixity_type"] == "sha512":
            if not re.match(r"^\w{128}$", fixity["fixity_value"]):
                raise ValueError("fixity_value for sha512 must be a 128-character string")
        else:
            raise ValueError("fixity_type must be one of: sha256, sha512")

    # Check that the files in the fixity block are all listed in the manifest
    if "files" not in fixity.keys():
        raise ValueError("Fixity block must contain a list of files")
    for file in fixity["files"]:
        if file not in manifest_files:
            raise ValueError("File %s is not listed in the manifest" % file)

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")
    for algorithm, fixes in fixity.items():
        if not isinstance(algorithm, str):
            raise ValueError("Algorithm must be a string")
        if not isinstance(fixes, dict):
            raise ValueError("Fixes must be a dictionary")
        for file_path, fix in fixes.items():
            if not isinstance(file_path, pathlib.PurePath):
                raise ValueError("File path must be a PurePath object")
            if not isinstance(fix, str):
                raise ValueError("Fix must be a string")
            if file_path not in manifest_files:
                raise ValueError(f"File {file_path} not found in manifest")
            if fix not in self.algorithms:
