def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages = []
    xml_files = []
    tmp_dict = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                xml_files.append(os.path.join(root, f))
    for xml_file in xml_files:
        package = {}
        tree = ElementTree.parse(xml_file)
        root = tree.getroot()
        basename = os.path.basename(xml_file)
        package['filename'] = basename
        package['version'] = root.find('version')
        package['release_status'] = root.find('release_status')
        packages.append(package)
    for package in packages:
        basename = package['filename']
        if basename in tmp_dict:
            tmp_dict[basename].append(package)
        else:
            tmp_dict[basename] = [package]
    return tmp_dict

