def _eval_file(prefix, filename, file_folder):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    packages: Dict[str, Any] = {}

    if prefix == "asset":
        packages[filename] = {"type": "asset", "file": file_folder + filename}
    elif prefix == "rendition":
        rendition_file = filename[filename.find("rendition") + 9:]
        packages[rendition_file] = {
            "type": "rendition",
            "file": file_folder + rendition_file,
        }
    else:
        packages[filename] = {"type": "unknown", "file": file_folder + filename}

    return packages

