def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg in new_args:
            continue
        for other_arg in new_args:
            if (arg.endswith("|") and other_arg.startswith(arg[:-1])) or (arg.startswith("|") and other_arg.endswith(arg[1:])):
                break
        else:
            new_args.append(arg)
    return new_args

