def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    if validate_objects:
        num_objects = 0
        good_objects = 0
        for obj in self.root.iterate_objects():
            num_objects += 1
            if obj.is_valid():
                good_objects += 1
        return (num_objects, good_objects)
    else:
        return None

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for obj in self.root.get_objects():
        num_objects += 1
        if validate_objects:
            if obj.validate():
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Warning: object {obj.name} failed validation")
        if check_digests:
            if obj.digest != obj.compute_digest():
                if show_warnings:
                    print(f"Warning: object {obj.name} failed digest check")
    return num_objects, good_objects

