def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return None

    version_parts = version.split('.')
    if len(version_parts) < 3:
        return None

    release_part = version_parts[0]
    major_part = version_parts[1]
    minor_part = version_parts[2]

    if release_part.startswith('0'):
        release_part = str(int(release_part) + 1).zfill(2)
    else:
        release_part = str(int(release_part) + 1)

    if major_part.startswith('0'):
        major_part = str(int(major_part) + 1).zfill(2)
    else:
        major_part = str(int(major_part) + 1)

    if minor_part.startswith('0'):
        minor_part = str(int(minor_part) + 1).zfill(2)
    else:
        minor_part = str(int(minor_part) + 1)

    return f"{release_part}.{major_part}.{minor_part}"

