def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(path, 'r') as f:
            for line in f:
                if line.startswith("0=*"):
                    if "OCFL_STORAGE_ROOT" in line:
                        return 'root'
                    elif "OCFL_OBJECT" in line:
                        return 'object'
                    elif "inventory" in line:
                        return 'file'
                    else:
                        return line # return the contents of the line
    except FileNotFoundError:
        return 'NOT_FOUND'
    return 'UNKNOWN'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        for entry in os.scandir(path):
            if entry.is_file() and entry.name.startswith("0="):
                if entry.name == "0=ocfl_object_1.0":
                    return "root"
                elif entry.name == "0=ocfl_object_0.0":
                    return "object"
                else:
                    return "file"
        return "unrecognized"
    except OSError:
        return "error"

