def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Check if the user has passed in valid params
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Check if the user has passed in valid bug IDs
    if not bug_ids or not isinstance(bug_ids, list):
        raise TypeError("bug_ids must be a list of integers")
    # Check if the user has passed in valid bug IDs
    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise TypeError("bug_ids must be a list of integers")
    # Replace the placeholder IDs with the actual bug IDs
    for param in params:
        if isinstance(params[param], str) and params[param].startswith("BZID-"):
            try:
                bug_id = int(params[param].split("-")[1])
            except ValueError:
                raise ValueError("Invalid bug ID")
            if bug_id not in bug_ids:
                raise ValueError("Invalid bug ID")
            params[param] = bug_id
    return params

