    except AssertionError:
        raise PermissionError("User does not have permission to edit the bug")

    # Amend the params
    for bug_id in bug_ids:
        bug = self.bugs.get(bug_id)
        for param in params:
            setattr(bug, param, params[param])
        self.bugs.put(bug)

