def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        host = host.lower()
        is_localhost = any(
            x in host for x in ["localhost", "127.0.0.1", "0.0.0.0", "::1", "0::1"]
        )
        if is_localhost:
            return True
        socket.gethostbyaddr(host)
        addr_info = socket.getaddrinfo(host, None, socket.AF_INET, socket.SOCK_STREAM)
        for a in addr_info:
            if a[4][0] == "127.0.0.1" or a[4][0] == "::1":
                return True
    except socket.error:
        pass
    return False

