    # Check if the candidate has all the required methods
    required_methods = [method for method in dir(iface) if callable(getattr(iface, method)) and not method.startswith('__')]
    for method in required_methods:
        if not hasattr(candidate, method) or not callable(getattr(candidate, method)):
