def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # LINKIFY TEXT LINKS
    def memoized_to_url(m):
        # to_url uses None to signal not to replace the text,
        # so we use a different sentinel value.
        value = memoized_urls.get(m.group(0), _NO_URL)
        if value is _NO_URL:
            value = to_url(m)
            memoized_urls[m.group(0)] = value
        return value

    def to_url(m):
        if m.group(1):
            return m.group(0)  # It's an http(s) url.
        path = m.group(0)

        if path.startswith('/'):
            path = os.path.relpath(path, buildroot)
        elif path.startswith('..'):
            # The path is not located inside the buildroot, so it's definitely not a BUILD file.
            return None
        else:
            # The path is located in the buildroot: see if it's a reference to a target in a BUILD file.
            parts = path.split(':')
            if len(parts) == 2:
                putative_dir = parts[0]
            else:
                putative_dir = path
            if os.path.isdir(os.path.join(buildroot, putative_dir)):
                build_files = list(BuildFile.get_build_files_family(
                    FileSystemProjectTree(buildroot),
                    putative_dir))
                if build_files:
                    path = build_files[0].relpath
                else:
                    return None

        if os.path.exists(os.path.join(buildroot, path)):
            # The reporting server serves file content at /browse/<path_from_buildroot>.
            return '/browse/{}'.format(path)
        else:
            return None

    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    text = _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

    # ADD ATTRIBUTES TO LINKS
    def link_attrs(self, func):
        """
        Add a callback for adding attributes to links.

        The callback should take a single argument, the url, and
        should return additional text to be inserted in the link tag,
        i.e. ``"target="_blank"``.

        You can use this method as a decorator on the function you
        want to set as the callback.
        """
        @libmarkdown.e_flags_callback
        def _link_attrs_func(string, size, context):
            ret = func(string[:size])
            if ret is not None:
                buf = ctypes.create_string_buffer(ret)
                self._alloc.append(buf)
                return ctypes.addressof(buf)

        self._link_attrs_func = _link_attrs_func
        return func

    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # define a function to linkify textual links
    def linkify(url):
        return '<a href="{}">{}</a>'.format(url, url)

    # define a function to add attributes to links
    def add_attrs(attrs):
        def _add_attrs(link):
            return '<a {} {}</a>'.format(attrs, link)
        return _add_attrs

    # find all links in the text
    links = re.findall(r'((https?:\/\/)?([\w\.]+)(\/[^\s]*)*)', text)

    # add attributes to links
    attrs = {'target': '_blank', 'rel': 'noopener noreferrer'}
    links = [add_attrs(attrs)(link) for link in links]

    # linkify textual links
    for link in links:
        text = text.replace(link, linkify(link))

    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    return _LINK_RE.sub(_link_attrs(text), text)

