            logger.error("Failed to parse Diaspora webfinger in XRD format")
            raise e

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        document_dict = json.loads(document)
    except json.JSONDecodeError:
        xrd_root = ElementTree.fromstring(document)
        xrd_subject = xrd_root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject")
        xrd_links = xrd_root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
        document_dict = {
            "subject": xrd_subject.text if xrd_subject is not None else None,
