def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise LookupError("yaml_file argument must be supplied")
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.load(f)
    except Exception as e:
        raise IRValidatorException(f"There was a problem parsing the file.  Diagnostic information follows.\n{e}")
    missing_data = []
    for required_field in cls.mandatory_fields:
        if required_field not in data:
            missing_data.append(required_field)
    if missing_data:
        raise IRValidatorException(f"The following mandatory fields are missing: {', '.join(missing_data)}")
    return data

def validate_from_file(cls, yaml_file: Path):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    # load YAML file
    with yaml_file.open() as f:
        data = yaml.load(f)

    errors = [{
        "file": "invalid"
    }]
    info = [{
        "file": yaml_file
    }]

    fields = {
        "config": {
            "type": "dict",
        },
        "name": {
            "type": "list",
            "schema": {
                "type": "str",
                "min": 1,
                "max": 100,
            },
        },
        "version": {
            "type": "str",
        },
        "destination": {
            "type": "str",
        },
        "actions": {
            "type": "list",
            "schema": {
                "type": "dict",
            },
        },
    }

    for field_name, field_schema in fields.items():
        if field_name not in data:
            errors.append({
                "file": yaml_file,
                "message": f"Missing required field '{field_name}'",
            })
            continue

        field_value = data[field_name]
        try:
            validate(field_value, field_schema)
        except ValidationError as exc:
            errors.append({
                "file": yaml_file,
                "message": f"Validation error in field '{field_name}': {exc.message}",
            })

    if errors:
        raise IRValidatorException(errors)

    return info, data

