            if include_dict:
                parser_dict.update(include_dict)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_dict = parser_dict.get('include_groups', {})
    for group_name, group_dict in include_dict.items():
        if group_name not in self.groups:
            self.groups[group_name] = []
        for name, arg in group_dict.items():
            if name not in self.arguments and not arg.get('hidden', False):
                self.arguments[name] = arg
                self.groups[group_name].append(name)
    return self

